#include "ws_crypto.h"
#include <stdint.h>
#include <string.h>
static uint32_t rol(uint32_t v,unsigned n){return(v<<n)|(v>>(32-n));}
static bool sha1(const uint8_t*data,size_t len,uint8_t out[20]){uint8_t msg[192]={0};size_t padded=((len+9+63)/64)*64;if(padded>sizeof(msg))return false;memcpy(msg,data,len);msg[len]=0x80;uint64_t bits=(uint64_t)len*8;for(int i=0;i<8;i++)msg[padded-1-i]=(uint8_t)(bits>>(8*i));uint32_t h[5]={0x67452301,0xefcdab89,0x98badcfe,0x10325476,0xc3d2e1f0};for(size_t block=0;block<padded;block+=64){uint32_t w[80];for(int i=0;i<16;i++)w[i]=((uint32_t)msg[block+4*i]<<24)|((uint32_t)msg[block+4*i+1]<<16)|((uint32_t)msg[block+4*i+2]<<8)|msg[block+4*i+3];for(int i=16;i<80;i++)w[i]=rol(w[i-3]^w[i-8]^w[i-14]^w[i-16],1);uint32_t a=h[0],b=h[1],c=h[2],d=h[3],e=h[4];for(int i=0;i<80;i++){uint32_t f,k;if(i<20){f=(b&c)|((~b)&d);k=0x5a827999;}else if(i<40){f=b^c^d;k=0x6ed9eba1;}else if(i<60){f=(b&c)|(b&d)|(c&d);k=0x8f1bbcdc;}else{f=b^c^d;k=0xca62c1d6;}uint32_t t=rol(a,5)+f+e+k+w[i];e=d;d=c;c=rol(b,30);b=a;a=t;}h[0]+=a;h[1]+=b;h[2]+=c;h[3]+=d;h[4]+=e;}for(int i=0;i<20;i++)out[i]=(uint8_t)(h[i/4]>>(24-8*(i&3)));return true;}
static void base64_20(const uint8_t in[20],char out[29]){static const char t[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";size_t o=0;for(size_t i=0;i<18;i+=3){uint32_t v=((uint32_t)in[i]<<16)|((uint32_t)in[i+1]<<8)|in[i+2];out[o++]=t[v>>18];out[o++]=t[(v>>12)&63];out[o++]=t[(v>>6)&63];out[o++]=t[v&63];}uint32_t v=((uint32_t)in[18]<<16)|((uint32_t)in[19]<<8);out[o++]=t[v>>18];out[o++]=t[(v>>12)&63];out[o++]=t[(v>>6)&63];out[o++]='=';out[o]=0;}
bool ws_crypto_accept(const char*key,size_t len,char output[29]){static const char guid[]="258EAFA5-E914-47DA-95CA-C5AB0DC85B11";if(!key||len>80)return false;uint8_t joined[117],hash[20];memcpy(joined,key,len);memcpy(joined+len,guid,sizeof(guid)-1);if(!sha1(joined,len+sizeof(guid)-1,hash))return false;base64_20(hash,output);return true;}
